:root {
  color-scheme: light;
  font:
    400 14px/1.5 Inter,
    system-ui,
    sans-serif;
  --canvas: #f7f9fa;
  --white: #fff;
  --text: #0f1820;
  --secondary: #3e5263;
  --border: #d4dbdf;
