  --blue: #046ac4;
  --blue-dark: #03559d;
  --blue-tint: #f2f7fc;
  --green: #3d7d0e;
  --green-tint: #f4faea;
  --red: #a0150a;
  --red-tint: #fcf8f8;
  --amber: #92430b;
  --amber-tint: #fef8f3;
}

* {
  box-sizing: border-box;
}
body {
  margin: 0;
  color: var(--text);
  background: var(--canvas);
}
h1,
h2,
