const assert = require('node:assert/strict');
const { spawn } = require('node:child_process');
const { chromium } = require('/private/tmp/glo35-browser-test/node_modules/playwright');

const origin = 'http://127.0.0.1:3146';
const frameId = 'FRM-00214';
const server = spawn(process.execPath, ['node_modules/next/dist/bin/next', 'start', '--hostname', '127.0.0.1', '--port', '3146'], { stdio: ['ignore', 'pipe', 'inherit'] });

async function run() {
  await new Promise((resolve, reject) => {
    const timeout = setTimeout(() => reject(new Error('Next.js startup timed out')), 8000);
    server.stdout.on('data', data => {
      if (data.toString().includes('Ready')) {
        clearTimeout(timeout);
        resolve();
      }
    });
    server.on('exit', code => {
      clearTimeout(timeout);
      reject(new Error('Next.js exited with code ' + code));
    });
  });

  const browser = await chromium.launch({ channel: 'chrome', headless: true });
  try {
    const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
    const errors = [];
    const loadedFonts = [];
    const queries = [];
    page.on('pageerror', error => errors.push(error.message));
    page.on('response', response => {
      if (response.ok() && response.request().resourceType() === 'font') loadedFonts.push(response.url());
    });
    await page.route('**/api/graphql', async route => {
      const { operationName, variables } = route.request().postDataJSON();
      queries.push({ operationName, variables });
      const attributes = {
        status: 'LIVE', statusReason: null, locationId: null, environment: null,
        siteNo: '214', address: 'Westminster', inventorySiteNo: null, panelNumber: null,
        station: null, airport: null, latitude: null, longitude: null,
        distanceToClosestSchool: null, location: null, format: null, sizeCode: null,
        aspectRatioCode: null, tSize: null, pixelHeight: null, pixelWidth: null,
        illuminationTypeId: null, numberOfSlots: null, impactWeight: null, premium: false,
        productionRateCard: null, productionRateCardLegacy: null, pricingGrade: null,
      };
      const frame = { frameId, attributes, externalReferences: [], linkedFrameIds: [] };
      const results = {
        Frames: { frames: { page: 0, size: 25, hasNext: false, items: [frame] } },
        FrameDetail: { frame },
        FrameHistory: { frameHistory: [{
          versionId: '1', validFrom: '2026-11-27T09:00:00Z', validTo: null, current: true,
          changeSource: null, closedByChangeSource: null, importJobId: null, attributes,
        }] },
      };
      assert.ok(results[operationName], 'Unexpected query: ' + operationName);
      await route.fulfill({ json: { data: results[operationName] } });
    });

    const matrix = async selector => page.locator(selector).evaluate(el => getComputedStyle(el).gridTemplateColumns.split(' ').length);
    const rgb = async (selector, property) => page.locator(selector).first().evaluate((element, key) => getComputedStyle(element)[key], property);
    await page.goto(origin);
    await page.getByRole('link', { name: frameId }).waitFor();
    assert.equal(await matrix('.workspace'), 2);
    assert.equal(await matrix('.inventory-results'), 2);
    const tokens = await page.evaluate(async () => {
      await Promise.all([400, 500, 600, 700].map(weight => document.fonts.load(weight + ' 14px Inter')));
      const css = getComputedStyle(document.documentElement);
      return [css.getPropertyValue('--primary-main').trim().toLowerCase(), css.getPropertyValue('--sp-2').trim()];
    });
    assert.deepEqual(tokens, ['#046ac4', '1rem']);
    assert.equal(loadedFonts.length, 4);
    assert.equal(await rgb('.button-primary', 'backgroundColor'), 'rgb(4, 106, 196)');
    assert.equal(await rgb('.chip', 'backgroundColor'), 'rgb(224, 236, 210)');
    assert.equal(await rgb('thead th', 'textTransform'), 'uppercase');

    await page.getByRole('searchbox').fill('FRM');
    await page.getByRole('button', { name: 'Search', exact: true }).click();
    await page.getByRole('link', { name: frameId }).waitFor();
    assert.ok(queries.some(({ variables }) => variables.search === 'FRM'));
    await page.getByRole('button', { name: 'Clear filters' }).click();
    await page.getByRole('button', { name: 'Add a frame' }).click();
    await page.getByRole('dialog', { name: 'Add a frame' }).waitFor();
    await page.keyboard.press('Escape');
    await page.getByRole('dialog').waitFor({ state: 'hidden' });

    await page.setViewportSize({ width: 390, height: 844 });
    assert.equal(await matrix('.workspace'), 1);
    assert.equal(await matrix('.inventory-results'), 1);
    assert.equal(await page.evaluate(() => document.documentElement.scrollWidth), 390);
    await page.getByRole('link', { name: frameId }).click();
    await page.getByRole('heading', { name: 'Location', exact: true }).waitFor();
    await page.getByRole('button', { name: 'Version history' }).click();
    await page.getByText('Version 1', { exact: true }).waitFor();
    await page.getByRole('button', { name: 'Close' }).click();
    await page.getByRole('button', { name: 'Imports', exact: true }).click();
    await page.getByLabel('Local operator token').waitFor();
    assert.equal(await page.evaluate(() => document.documentElement.scrollWidth), 390);
    assert.deepEqual(errors, []);
    console.log('Desktop and mobile layout, four Inter weights, token styles, search, create dialog, detail, history, and Imports passed.');
  } finally {
    await browser.close();
  }
}

run().catch(error => {
  console.error(error);
  process.exitCode = 1;
}).finally(() => server.kill());
