.import-card {
  padding: 20px;
  display: grid;
  gap: 12px;
}
.fields,
.job-summary {
  display: grid;
  gap: var(--sp-2);
}
.field {
  display: grid;
  gap: 4px;
  font-size: var(--fs-label);
  font-weight: var(--fw-medium);
  min-width: 0;
}
.field .subtle {
  font-weight: var(--fw-regular);
  font-size: 13px;
}
.field input,
.field select {
  width: 100%;
  min-width: 0;
  min-height: 36px;
  border: 1px solid var(--border-default);
  padding: 0 12px;
  border-radius: var(--radius);
  background: var(--bg-default);
  color: var(--text-primary);
  font-size: 13px;
  font-weight: var(--fw-regular);
}
